begin;
create function app_private.guard_field_record() returns trigger language plpgsql set search_path='' as $$begin
 if tg_op='DELETE' then raise exception 'field history retained' using errcode='55000';end if;
 if tg_table_name='field_campaigns' then
 if old.customer_approved_by is not null or(to_jsonb(new)-array['customer_approved_by','customer_approved_at','updated_at'])<>(to_jsonb(old)-array['customer_approved_by','customer_approved_at','updated_at']) then raise exception 'campaign specification and approved form immutable' using errcode='55000';end if;
 elsif tg_table_name='field_campaign_locations' then
 if old.status in ('client_accepted','cancelled') or(to_jsonb(new)-array['task_id','status','client_approved_by','updated_at'])<>(to_jsonb(old)-array['task_id','status','client_approved_by','updated_at']) then raise exception 'location target and accepted deliverable immutable' using errcode='55000';end if;
 elsif tg_table_name='field_campaign_submissions' then
 if old.status in ('rejected','client_accepted') or(to_jsonb(new)-array['status','reviewed_by','updated_at'])<>(to_jsonb(old)-array['status','reviewed_by','updated_at']) then raise exception 'field answers and historical decisions immutable' using errcode='55000';end if;
 end if;return new;end$$;
do $$declare name text;begin foreach name in array array['field_campaigns','field_campaign_locations','field_campaign_submissions'] loop execute format('create trigger field_guard before update or delete on private.%I for each row execute function app_private.guard_field_record()',name);end loop;end$$;
alter function app_private.read_service_operation(uuid,uuid,integer) rename to read_operation_before_field;
revoke all on function app_private.read_operation_before_field(uuid,uuid,integer) from public,anon,authenticated;
create function app_private.read_service_operation(p_operation uuid,p_after uuid default null,p_limit integer default 25) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare operation private.service_operations;result jsonb;staff boolean;begin
 result=app_private.read_operation_before_field(p_operation,p_after,p_limit);select * into operation from private.service_operations where id=p_operation;
 if operation.kind<>'field_campaign' then return result;end if;
 staff=app_private.operation_staff(operation.id,'specialized.read') or app_private.operation_staff(operation.id);
 result=result||jsonb_build_object('campaign',(select jsonb_build_object('id',id,'reference',reference,'start',starts_at,'end',ends_at,'customer_approved_at',customer_approved_at,'specification',case when staff or(app_private.order_customer(operation.primary_order_id) and not exists(select 1 from private.operation_orders member where member.operation_id=operation.id and not app_private.order_customer(member.order_id))) then specification else '{}'::jsonb end) from private.field_campaigns where operation_id=operation.id),
 'locations',(select coalesce(jsonb_agg(jsonb_build_object('id',page.id,'reference',page.external_reference,'location',page.location_snapshot,'milestone',page.milestone,'status',page.status,'mandatory',page.mandatory,'task_id',case when staff or app_private.execution_worker(page.task_id) then page.task_id end,
 'submissions',(select coalesce(jsonb_agg(jsonb_build_object('id',submission.id,'version',submission.version,'status',submission.status,'answers',response.answers,'submitted_at',response.created_at,'location_provenance','declared')),'[]') from private.field_campaign_submissions submission join private.execution_submissions response on response.id=submission.execution_submission_id where submission.location_id=page.id and(staff or app_private.execution_worker(page.task_id) or(submission.status in ('quality_approved','client_accepted') and app_private.order_customer(page.authorized_order_id)))))),'[]') from(select location.*,task.order_id as authorized_order_id from private.field_campaign_locations location join private.work_tasks task on task.id=location.task_id where location.operation_id=operation.id and(staff or app_private.execution_worker(task.id) or app_private.order_customer(task.order_id)) and(p_after is null or location.id>p_after) order by location.id limit p_limit) page));return result;end$$;
grant execute on function app_private.read_service_operation(uuid,uuid,integer) to authenticated;
create or replace function public.read_service_operation(p_operation uuid,p_after uuid default null,p_limit integer default 25) returns jsonb language sql stable set search_path='' as $$select app_private.read_service_operation(p_operation,p_after,p_limit)$$;
create function app_private.list_service_operations(p_queue text,p_kind text default null,p_zone uuid default null,p_city uuid default null,p_after uuid default null,p_limit integer default 25) returns jsonb language plpgsql stable security definer set search_path='' as $$begin
 if auth.uid() is null or p_limit is null or p_limit not between 1 and 100 or p_queue not in ('all','laundry_pickup','laundry_processing','laundry_exceptions','laundry_delivery','construction_progress','construction_changes','procurement_rfqs','procurement_receiving','field_review','field_progress','exceptions') or(p_kind is not null and p_kind not in ('laundry','construction','procurement','field_campaign')) then raise exception 'bounded typed operations queue required' using errcode='23514';end if;
 return(select coalesce(jsonb_agg(jsonb_build_object('id',page.id,'reference',page.reference,'kind',page.kind,'status',page.status,'revision',page.revision,'zone_id',page.zone_id,'city_id',page.city_id)),'[]') from(select operation.id,operation.reference,operation.kind,operation.status,operation.revision,case when app_private.operation_staff(operation.id,'specialized.read') or app_private.operation_staff(operation.id) or app_private.order_customer(parent.id) or(operation.kind='procurement' and app_private.procurement_supplier_access(operation.id)) or exists(select 1 from private.operation_tasks visible where visible.operation_id=operation.id and visible.order_id=parent.id and app_private.execution_worker(visible.task_id)) then parent.zone_id end as zone_id,case when app_private.operation_staff(operation.id,'specialized.read') or app_private.operation_staff(operation.id) or app_private.order_customer(parent.id) or(operation.kind='procurement' and app_private.procurement_supplier_access(operation.id)) or exists(select 1 from private.operation_tasks visible where visible.operation_id=operation.id and visible.order_id=parent.id and app_private.execution_worker(visible.task_id)) then site.city_id end as city_id from private.service_operations operation join private.service_orders parent on parent.id=operation.primary_order_id join public.service_locations site on site.id=parent.service_location_id where app_private.operation_access(operation.id) and(p_after is null or operation.id>p_after) and(p_kind is null or operation.kind=p_kind) and((p_zone is null and p_city is null) or exists(select 1 from private.operation_orders member join private.service_orders scoped_order on scoped_order.id=member.order_id join public.service_locations scoped_site on scoped_site.id=scoped_order.service_location_id where member.operation_id=operation.id and(p_zone is null or scoped_order.zone_id=p_zone) and(p_city is null or scoped_site.city_id=p_city) and(app_private.operation_staff(operation.id,'specialized.read') or app_private.operation_staff(operation.id) or app_private.order_customer(scoped_order.id) or(operation.kind='procurement' and app_private.procurement_supplier_access(operation.id)) or exists(select 1 from private.operation_tasks visible where visible.operation_id=operation.id and visible.order_id=scoped_order.id and app_private.execution_worker(visible.task_id))))) and
 (p_queue='all'
 or(p_queue='laundry_pickup' and operation.kind='laundry' and operation.status in ('planning','active') and exists(select 1 from private.laundry_custody_balances where operation_id=operation.id and customer_holder and units>0))
 or(p_queue='laundry_processing' and exists(select 1 from private.laundry_processing_batches where operation_id=operation.id and status in ('allocated','received','processing','quality_review')))
 or(p_queue='laundry_delivery' and exists(select 1 from private.laundry_processing_batches where operation_id=operation.id and status='packaged'))
 or(p_queue in ('laundry_exceptions','exceptions') and exists(select 1 from private.laundry_custody_transfers where operation_id=operation.id and status='discrepant'))
 or(p_queue='construction_progress' and operation.kind='construction' and operation.status in ('planning','active'))
 or(p_queue='construction_changes' and exists(select 1 from private.construction_variations where operation_id=operation.id and status in ('proposed','customer_accepted','approved')))
 or(p_queue='procurement_rfqs' and exists(select 1 from private.procurement_rfqs where operation_id=operation.id and status in ('draft','issued')))
 or(p_queue='procurement_receiving' and exists(select 1 from private.purchase_orders where operation_id=operation.id and status in ('acknowledged','part_received','received')))
 or(p_queue='field_review' and exists(select 1 from private.field_campaign_locations location join private.work_tasks task on task.id=location.task_id where location.operation_id=operation.id and location.status in ('submitted','rework') and(app_private.operation_staff(operation.id,'specialized.read') or app_private.execution_worker(task.id) or app_private.order_customer(task.order_id))))
 or(p_queue='field_progress' and operation.kind='field_campaign' and operation.status in ('planning','active'))
 or(p_queue='exceptions' and exists(select 1 from private.service_cases issue join private.operation_orders member on member.order_id=issue.order_id where member.operation_id=operation.id and issue.status not in ('resolved','closed') and app_private.case_access(issue.id)))) order by operation.id limit p_limit) page);
end$$;
create function public.list_service_operations(p_queue text,p_kind text default null,p_zone uuid default null,p_city uuid default null,p_after uuid default null,p_limit integer default 25) returns jsonb language sql stable set search_path='' as $$select app_private.list_service_operations(p_queue,p_kind,p_zone,p_city,p_after,p_limit)$$;
revoke all on function public.list_service_operations(text,text,uuid,uuid,uuid,integer) from public,anon;
grant execute on function public.list_service_operations(text,text,uuid,uuid,uuid,integer),app_private.list_service_operations(text,text,uuid,uuid,uuid,integer) to authenticated;

create function app_private.specialized_document_access(p_document uuid) returns boolean language sql stable security definer set search_path='' as $$
 select exists(select 1 from private.document_objects document where document.id=p_document and document.scan_status='clean' and document.archived_at is null and(
 exists(select 1 from private.laundry_custody_transfers transfer join private.execution_evidence evidence on evidence.id=transfer.evidence_id join private.service_operations operation on operation.id=transfer.operation_id and operation.status='active' where evidence.document_id=document.id and evidence.status='approved' and(app_private.operation_resource(operation.id,transfer.destination_resource_id) or exists(select 1 from private.laundry_transfer_items line join private.laundry_custody_balances balance on balance.id=line.source_balance_id where line.transfer_id=transfer.id and app_private.operation_resource(operation.id,balance.resource_id))))
 or exists(select 1 from private.supplier_eligibility_versions eligibility where eligibility.document_id=document.id and document.organisation_id=eligibility.organisation_id and(app_private.supplier_actor(eligibility.organisation_id) or app_private.has_permission('procurement.source') or app_private.has_permission('procurement.approve')))
 or exists(select 1 from private.procurement_receipts receipt join private.purchase_order_versions version on version.id=receipt.version_id join private.purchase_orders po on po.id=version.purchase_order_id where receipt.shipping_document_id=document.id and document.organisation_id=po.supplier_organisation_id and(app_private.supplier_actor(po.supplier_organisation_id) or app_private.operation_staff(po.operation_id,'procurement.source') or app_private.execution_worker(receipt.receiving_task_id)))))
$$;
alter function app_private.can_read_object(text,text) rename to before_specialized_can_read_object;
revoke all on function app_private.before_specialized_can_read_object(text,text) from public,anon,authenticated;
create function app_private.can_read_object(p_bucket text,p_name text) returns boolean language sql stable security definer set search_path='' as $$select app_private.before_specialized_can_read_object(p_bucket,p_name) or exists(select 1 from private.document_objects where bucket_id=p_bucket and object_name=p_name and app_private.specialized_document_access(id))$$;
grant execute on function app_private.can_read_object(text,text) to anon,authenticated;
do $$declare policy record;begin for policy in select policyname,qual from pg_policies where schemaname='storage' and tablename='objects' and qual like '%before_specialized_can_read_object%' loop execute format('alter policy %I on storage.objects using (%s)',policy.policyname,replace(policy.qual,'before_specialized_can_read_object','can_read_object'));end loop;end$$;
create function app_private.specialized_document_reference(p_operation uuid,p_document uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$declare document private.document_objects;begin
 if not app_private.operation_access(p_operation) then raise exception 'operation document unavailable' using errcode='42501';end if;
 select * into document from private.document_objects where id=p_document;
 if document.id is null or not app_private.can_read_object(document.bucket_id,document.object_name) or not(
 exists(select 1 from private.operation_documents where operation_id=p_operation and document_id=document.id)
 or exists(select 1 from private.execution_evidence evidence join private.operation_tasks link on link.task_id=evidence.task_id where link.operation_id=p_operation and evidence.document_id=document.id)
 or exists(select 1 from private.procurement_receipts where operation_id=p_operation and shipping_document_id=document.id)
 or exists(select 1 from private.supplier_eligibility_versions eligibility join private.procurement_rfq_recipients recipient on recipient.eligibility_id=eligibility.id join private.procurement_rfqs rfq on rfq.id=recipient.rfq_id where rfq.operation_id=p_operation and eligibility.document_id=document.id)) then raise exception 'exact linked document authority required' using errcode='42501';end if;
 return jsonb_build_object('document_id',document.id,'bucket_id',document.bucket_id,'object_name',document.object_name,'scan_status',document.scan_status);end$$;
create function public.specialized_document_reference(p_operation uuid,p_document uuid) returns jsonb language sql stable set search_path='' as $$select app_private.specialized_document_reference(p_operation,p_document)$$;
revoke all on function public.specialized_document_reference(uuid,uuid) from public,anon;
grant execute on function public.specialized_document_reference(uuid,uuid),app_private.specialized_document_reference(uuid,uuid) to authenticated;
revoke all on function app_private.specialized_document_access(uuid) from public,anon,authenticated;
commit;
